import { test, expect } from '@playwright/test';

test.describe('Change Password from Profile Settings', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
    await page.getByRole('button', { name: /settings/i }).click();
    await page.getByRole('link', { name: /security/i }).click();
  });

  test('should successfully change password with valid credentials', async ({ page }) => {
    // Verify current password field is visible
    const currentPasswordField = page.getByLabel(/current password/i);
    await expect(currentPasswordField).toBeVisible();

    // Fill in current password
    await currentPasswordField.fill('ValidCurrentPassword123');

    // Fill in new password
    const newPasswordField = page.getByLabel(/new password/i);
    await newPasswordField.fill('NewSecurePassword123!');

    // Fill in confirm new password
    const confirmPasswordField = page.getByLabel(/confirm new password/i);
    await confirmPasswordField.fill('NewSecurePassword123!');

    // Click change password button
    const changePasswordButton = page.getByRole('button', { name: /change password/i });
    await expect(changePasswordButton).toBeVisible();
    await changePasswordButton.click();

    // Wait for success message
    const successMessage = page.getByText(/password changed successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify success message contains correct text
    await expect(successMessage).toContainText('Password changed successfully');

    // Verify user is redirected to profile page
    await expect(page).toHaveURL(/.*\/profile/);
  });

  test('should display error when new password does not meet complexity requirements', async ({ page }) => {
    // Fill in current password
    const currentPasswordField = page.getByLabel(/current password/i);
    await currentPasswordField.fill('ValidCurrentPassword123');

    // Fill in new password that is too short
    const newPasswordField = page.getByLabel(/new password/i);
    await newPasswordField.fill('short');

    // Fill in confirm new password
    const confirmPasswordField = page.getByLabel(/confirm new password/i);
    await confirmPasswordField.fill('short');

    // Click change password button
    const changePasswordButton = page.getByRole('button', { name: /change password/i });
    await changePasswordButton.click();

    // Wait for error message
    const errorMessage = page.getByText(/password must be at least 8 characters/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message contains required text
    await expect(errorMessage).toContainText('at least 8 characters');

    // Verify success message does not appear
    const successMessage = page.getByText(/password changed successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify user remains on the security page
    await expect(page).toHaveURL(/.*\/profile\/security/);
  });

  test('should display error when new password and confirmation do not match', async ({ page }) => {
    // Fill in current password
    const currentPasswordField = page.getByLabel(/current password/i);
    await currentPasswordField.fill('ValidCurrentPassword123');

    // Fill in new password
    const newPasswordField = page.getByLabel(/new password/i);
    await newPasswordField.fill('NewSecurePassword123!');

    // Fill in mismatched confirm new password
    const confirmPasswordField = page.getByLabel(/confirm new password/i);
    await confirmPasswordField.fill('DifferentPassword123!');

    // Click change password button
    const changePasswordButton = page.getByRole('button', { name: /change password/i });
    await changePasswordButton.click();

    // Wait for mismatch error
    const mismatchError = page.getByText(/new password and confirmation do not match/i);
    await expect(mismatchError).toBeVisible();

    // Verify error message contains required text
    await expect(mismatchError).toContainText('do not match');

    // Verify success message does not appear
    const successMessage = page.getByText(/password changed successfully/i);
    await expect(successMessage).not.toBeVisible();
  });
});
